WITH EmployeesByDepartment AS (SELECT dept_id, MAX(hire_date) AS latest_hire_date, AVG(salary) AS avg_salary FROM employees WHERE is_remote = TRUE GROUP BY dept_id) SELECT departments.id, departments.location, departments.budget, EmployeesByDepartment.latest_hire_date, EmployeesByDepartment.avg_salary FROM departments LEFT JOIN EmployeesByDepartment ON departments.id = EmployeesByDepartment.dept_id WHERE EmployeesByDepartment.avg_salary >= 123000;
